def is_connected_cells(cells):
    """Check if all cells are connected via 4-way adjacency"""
    if not cells:
        return True
    visited = set()
    to_visit = [cells[0]]
    visited.add(cells[0])

    while to_visit:
        cr, cc = to_visit.pop()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
