def block_quadrant(cr, cc):
    """Find which quadrant (0,1,2,3) cell is in"""
    if cr < 1.5 and cc < 1.5:
        return 0  # top-left
    elif cr < 1.5 and cc >= 1.5:
        return 1  # top-right
    elif cr >= 1.5 and cc < 1.5:
        return 2  # bottom-left
    else:
        return 3  # bottom-right

